def max_product(nums):
    """
    Calculate the maximum product formed by multiplying numbers of an increasing subsequence of the input array.
    """
    def find_max_product_helper(nums, start):
        if start >= len(nums):
            return 1
        max_product = 1
        for i in range(start, len(nums)):
            max_product *= nums[i]
        return max_product

    def find_max_product(nums):
        max_product = 1
        for i in range(len(nums)):
            if nums[i] > max_product:
                max_product = find_max_product_helper(nums, i)
        return max_product - 1  # Subtract 1 to adjust for the initial value set

    def increasing_subsequence_product(nums):
        max_product = 1
        for i in range(len(nums)):
            if i > 0 and nums[i] > nums[i-1]:
                max_product *= nums[i]
            else:
                max_product = find_max_product_helper(nums, i)
                break
        return max_product - 1  # Subtract 1 to adjust for the initial value set

    return increasing_subsequence_product(nums)

